[data-theme-style="qq"] .msg-transfer-card .msg-transfer-divider,
[data-theme-style="qq"] .msg-transfer-card .msg_transfer_check,
[data-theme-style="qq"] .msg-transfer-card .msg-transfer-chevron,
[data-theme-style="qq"] .msg-transfer-card .msg-transfer-label,
[data-theme-style="qq"] .msg-transfer-card .msg-transfer-status-text {
