}


/* ============================================================
   模块五：语音消息（播放按钮 18px，可点击）
   ============================================================ */

[data-theme-style="qq"] .voice-play-btn {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 18px !important;
    height: 18px !important;
    flex-shrink: 0 !important;
    margin-right: 4px !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    cursor: pointer !important;
    position: relative !important;   /* 确保 z-index 生效 */
    z-index: 11 !important;          /* 高于翻译覆盖层 (z-index:10) */
}

/* 我方播放按钮颜色 = 波形已播放条颜色（#2a2a2a） */
[data-theme-style="qq"] .voice-msg-me .voice-play-btn {
    color: #2a2a2a !important;
}

/* 对方播放按钮颜色 = 波形已播放条颜色（#ffffff） */
[data-theme-style="qq"] .voice-msg-them .voice-play-btn {
    color: #ffffff !important;
}

/* 按钮内的 SVG 使用当前颜色 */
[data-theme-style="qq"] .voice-play-btn svg {
    fill: currentColor !important;
    stroke: currentColor !important;
    width: 100% !important;
    height: 100% !important;
}

/* 其余布局保持不变 */
[data-theme-style="qq"] .voice-controls-row {
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    padding: 0 !important;
    width: 100% !important;
}

[data-theme-style="qq"] .voice-waveform {
    flex: 1 1 auto !important;
    min-width: 30px !important;
}

[data-theme-style="qq"] .voice-duration {
    flex-shrink: 0 !important;
}

[data-theme-style="qq"] .voice-msg-me {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-end !important;
    width: 100% !important;
}

[data-theme-style="qq"] .voice-msg-me .voice-controls-row {
    width: auto !important;
    max-width: 100% !important;
    margin-left: auto !important;
}

[data-theme-style="qq"] .voice-msg-me .voice-waveform-bar {
    background-color: #2a2a2a !important;
