    min-width: 140px !important;
}
.msg-translation-content {
    display: none !important;
}
.msg-translation-detached-them {
    align-self: flex-start !important;
}
.msg-translation-detached-me {
    align-self: flex-end !important;
}
.msg-translation-detached-content {
    background: var(--trans-detached-bg) !important;
    color: var(--trans-detached-color) !important;
    padding: 8px 12px 28px 12px !important;
    border-radius: var(--reply-detached-radius) !important;
