.msg-translation-detached-content::before {
    content: "";
    position: absolute;
    left: 13px;
    bottom: 12px;
    width: 11px;
    height: 11px;
    background: var(--trans-btn1);
    border-radius: 50%;
    background-image: linear-gradient(45deg, transparent 40%, #fff 40%, #fff 50%, transparent 50%),
                       linear-gradient(-45deg, transparent 55%, #fff 55%, #fff 65%, transparent 65%);
    background-size: 8px 8px;
    background-position: center;
    background-repeat: no-repeat;
}
.msg-translation-detached-content::after {
    content: "由微信提供翻译支持";
    position: absolute;
    left: 27px;
    bottom: 9px;
    font-size: 11px;
