    flex-direction: column !important;
    align-items: flex-end !important;
}
.msg-them .voice-controls-row {
    padding: 7.3px 0 7.3px 7px !important;
    background: var(--bubble-them-bg) !important;
}
.voice-controls-row::after {
    content: "";
    position: absolute;
    top: 50%;
    width: 8px;
    height: 8px;
    border-radius: 1.5px;
    transform: rotate(45deg);
}
.voice-transcription-toggle {
    position: absolute !important;
    top: 12px !important;
    width: 52px !important;
    margin-left: 24px;
    padding: 0 !important;
